  source: 'pragma cashscript ^0.14.0;\n\n// Largest miner fee, in satoshis, an agent spend may pay. Anything not sent to\n// a payment or back to the vault is a fee, so this stops fee-based skimming.\nint constant MAXIMUM_MINER_FEE_SATOSHIS = 2000;\n\n// Each approved recipient is stored as a 20-byte public key hash.\nint constant RECIPIENT_ENTRY_BYTE_LENGTH = 20;\n\n// First byte of a standard data-carrier (OP_RETURN) locking bytecode.\nbytes1 constant OP_RETURN_BYTE = 0x6a;\n\n// A spending mandate: the owner funds one vault output and an agent key may\n// spend it only inside these terms. The owner key can sweep the vault at any\n// time, which is also how an allowance is ended early.\ncontract CashMandate(\n    bytes20 ownerPublicKeyHash,\n    pubkey agentPublicKey,\n    bytes32 approvedRecipientsHash,\n    int perSpendLimitSatoshis,\n    int minimumBlocksBetweenSpends\n) {\n    // Agent spend. Output 0 pays an approved recipient no more than the\n    // per-spend limit. Output 1 returns the rest to this same contract, so the\n    // next spend is a fresh output whose age restarts at zero. Optional output\n    // 2 is a zero-value OP_RETURN memo recording why the agent paid.\n    function spend(sig agentSignature, bytes approvedRecipients, int recipientIndex) {\n        require(checkSig(agentSignature, agentPublicKey));\n\n        // Rate limit: the vault output must be old enough, and the fresh\n        // output created below makes the clock start over.\n        require(this.age >= minimumBlocksBetweenSpends);\n\n        // One input only, so a second vault output cannot be spent in the\n        // same transaction to double the per-spend limit.\n        require(tx.inputs.length == 1);\n\n        // Recipient policy: the supplied list must hash to the committed\n        // value, and the payment must go to the entry at the given index.\n        require(sha256(approvedRecipients) == approvedRecipientsHash);\n        bytes remainingList = approvedRecipients.split(recipientIndex * RECIPIENT_ENTRY_BYTE_LENGTH)[1];\n        bytes recipientEntry = remainingList.split(RECIPIENT_ENTRY_BYTE_LENGTH)[0];\n        bytes25 recipientLockingBytecode = new LockingBytecodeP2PKH(unsafe_bytes20(recipientEntry));\n\n        int vaultValue = tx.inputs[0].value;\n        require(tx.outputs.length >= 2);\n        require(tx.outputs.length <= 3);\n\n        // Payment output.\n        require(tx.outputs[0].lockingBytecode == recipientLockingBytecode);\n        require(tx.outputs[0].value <= perSpendLimitSatoshis);\n        require(tx.outputs[0].tokenCategory == 0x);\n\n        // Continuation output: same covenant, remainder preserved.\n        require(tx.outputs[1].lockingBytecode == tx.inputs[0].lockingBytecode);\n        require(tx.outputs[1].value >= vaultValue - tx.outputs[0].value - MAXIMUM_MINER_FEE_SATOSHIS);\n        require(tx.outputs[1].tokenCategory == 0x);\n\n        // Memo output, when present, carries no value.\n        if (tx.outputs.length == 3) {\n            require(tx.outputs[2].value == 0);\n            require(tx.outputs[2].lockingBytecode.split(1)[0] == OP_RETURN_BYTE);\n        }\n    }\n\n    // Owner control. The owner may move the vault anywhere at any time.\n    function revoke(pubkey ownerPublicKey, sig ownerSignature) {\n        require(hash160(ownerPublicKey) == ownerPublicKeyHash);\n        require(checkSig(ownerSignature, ownerPublicKey));\n    }\n}\n',
